<?php declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$token=$_GET['token']??'';if(!preg_match('/^[a-f0-9]{64}$/',$token)){flash('error','That verification link is invalid.');redirect('login');}$pdo=db();$stmt=$pdo->prepare('SELECT vt.*,u.owner_id,u.role FROM verification_tokens vt JOIN users u ON u.id=vt.user_id WHERE vt.token_hash=? AND vt.used_at IS NULL AND vt.expires_at>NOW() LIMIT 1');$stmt->execute([hash('sha256',$token)]);$record=$stmt->fetch();if(!$record){flash('error','That verification link is invalid or expired.');redirect('login');}$pdo->beginTransaction();$pdo->prepare('UPDATE users SET is_email_verified=1 WHERE id=?')->execute([$record['user_id']]);if($record['role']==='OWNER_ADMIN'){$pdo->prepare('UPDATE owners SET is_email_verified=1 WHERE id=?')->execute([$record['owner_id']]);}$pdo->prepare('UPDATE verification_tokens SET used_at=NOW() WHERE id=?')->execute([$record['id']]);$pdo->commit();unset($_SESSION['dev_verification_url']);flash('success','Email verified. Your operational access is now unlocked.');redirect(!empty($_SESSION['user_id'])?'dashboard':'login');
